# region: gather
def gather(raw):
    out = []
    for tok in raw[1:]:
        s = tok.strip()
        if s.isdigit() and int(s) > 0:
            out.append(int(s))
    return out

# region: shape
def shape(xs, factor=2):
    return [v * factor for v in xs]

# region: intake
def intake(xs, offset=4):
    return [v + offset for v in xs]

# region: fold
def fold(xs):
    d = {}
    for v in xs:
        d[v % 3] = d.get(v % 3, 0) + 1
    return {'n': len(xs), 'tally': sorted(d.items())}

# region: emit
def emit(summary, bar=3):
    out = dict(summary)
    out['grade'] = 'high' if summary.get('n', 0) >= bar else 'low'
    return out

# region: run
def run(raw):
    return emit(fold(intake(shape(gather(raw)))))

